message_template.source:
⚠️ PostgreSQL/Patroni Errors Detected

Monitor: {{ctx.monitor.name}}
Trigger: {{ctx.trigger.name}}
Severity: {{ctx.trigger.severity}}
Period: {{ctx.periodStart}} to {{ctx.periodEnd}}

📊 ERRORS BY HOST:
{{#ctx.results.0.aggregations.by_host.buckets}}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🖥️  Host: {{key}}
📈 Error Count: {{doc_count}}

📂 Errors by Log File:
{{#by_source.buckets}}
  📄 {{key}}
  Recent Errors:
{{#recent_errors.hits.hits}}
    [{{_source.@timestamp}}] {{_source._raw}}
{{/recent_errors.hits.hits}}

{{/by_source.buckets}}

📋 Sample Error Logs:
{{#error_logs.hits.hits}}
  ⏰ {{_source.@timestamp}}
  📝 {{_source._raw}}
  📁 Source: {{_source.source}}
  ---
{{/error_logs.hits.hits}}

{{/ctx.results.0.aggregations.by_host.buckets}}

💡 TO VIEW CONTEXT (±5 lines around errors):
For each error timestamp above, query OpenSearch:
  GET /postgresdata/_search
  {
    "query": {
      "bool": {
        "filter": [
          {"term": {"source.keyword": "<log_file_from_above>"}},
          {"range": {"@timestamp": {"gte": "<error_time_minus_1min>", "lte": "<error_time_plus_1min>"}}}
        ]
      }
    },
    "sort": [{"@timestamp": "asc"}],
    "size": 100
  }

Or check log files directly:
  tail -100 /var/log/postgresql/<source_file> | grep -C 5 '<error_keyword>'

custom_webhook.body:
{"to": ["admin@example.com"], "subject": "⚠️ PostgreSQL Errors - {{ctx.trigger.name}}", "body": "<html><body><h2>PostgreSQL/Patroni Errors Detected</h2><p><strong>Monitor:</strong> {{ctx.monitor.name}}<br><strong>Severity:</strong> {{ctx.trigger.severity}}<br><strong>Period:</strong> {{ctx.periodStart}} to {{ctx.periodEnd}}</p><h3>Errors by Host</h3>{{#ctx.results.0.aggregations.by_host.buckets}}<div style='border:1px solid #ccc; padding:10px; margin:10px 0;'><h4>Host: {{key}} ({{doc_count}} errors)</h4><h5>By Log File:</h5>{{#by_source.buckets}}<p><strong>{{key}}</strong></p><ul>{{#recent_errors.hits.hits}}<li>[{{_source.@timestamp}}] {{_source._raw}}</li>{{/recent_errors.hits.hits}}</ul>{{/by_source.buckets}}<h5>Sample Logs:</h5><pre>{{#error_logs.hits.hits}}[{{_source.@timestamp}}] {{_source._raw}}
Source: {{_source.source}}
---
{{/error_logs.hits.hits}}</pre></div>{{/ctx.results.0.aggregations.by_host.buckets}}<p><em>Note: Query OpenSearch with error timestamps ±1min filtered by source file to see surrounding log context</em></p></body></html>"}
